content.text:
                    best_class = c
            conn_predictions[i] = best_class
        out_connections.append({
            "id": conn_ids[i],
            "split": "dev" if conn_split[i] == 0 else "eval",
            "label": conn_label[i],
            "packets": counts[i],
            "votes": v,
            "prediction": conn_predictions[i],
        })

    # --- reports ---------------------------------------------------------
    confusions = [
        [[0] * classes for _ in range(classes)],
        [[0] * classes for _ in range(classes)],
    ]
    observed = [0, 0]
    for i in range(n_conn):
        if counts[i] == 0:
            continue
        split = conn_split[i]
        observed[split] += 1
        confusions[split][conn_label[i]][conn_predictions[i]] += 1

    reports = {}
    for name, split in (("dev", 0), ("eval", 1)):
        confusion = confusions[split]
        num = 0
        den = 1
        for c in range(classes):
            tp = confusion[c][c]
            col = 0
            for r in range(classes):
                col += confusion[r][c]
            row = 0
            for x in confusion[c]:
                row += x
            fp = col - tp
            fn = row - tp
            denom = 2 * tp + fp + fn
            if denom == 0:
                continue
            num = num * denom + 2 * tp * den
            den *= denom
        den *= classes
        g = gcd(num, den)
        if g > 1:
            num //= g
            den //= g
        if den == 0:
            den = 1
        reports[name] = {
            "connections": observed[split],
            "confusion": confusion,
            "macro_f1": [num, den],
        }

    return {
        "packets": out_packets,
        "jobs": all_jobs,
        "connections": out_connections,
        "reports": reports,
    }


